record.field:
# 1% desde 4 SMMLV, escala adicional desde 16 SMMLV
_params = employee.company_id._get_co_payroll_params(payslip.date_from)
SMMLV = _params.smmlv
ibc = categories['DEV_SAL']
if contract.l10n_co_ne_integral_salary:
    ibc = contract.wage * 0.70
pct = 0.01  # 1% base
if ibc >= SMMLV * 20:
    pct = 0.02
elif ibc >= SMMLV * 19:
    pct = 0.018
elif ibc >= SMMLV * 18:
    pct = 0.016
elif ibc >= SMMLV * 17:
    pct = 0.014
elif ibc >= SMMLV * 16:
    pct = 0.012
result = -abs(ibc * pct)
